// 1) Safisha na hakiki namba ya simu ya Tanzania, rudisha item moja kwa lead
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  let phone = String(b.phone ?? '').replace(/[^0-9+]/g, '');
  if (phone.startsWith('00')) phone = phone.slice(2);
  if (phone.startsWith('0')) phone = '+255' + phone.slice(1);
  else if (phone.startsWith('255')) phone = '+' + phone;
  if (!/^\+255\d{9}$/.test(phone)) continue; // lead isiyo na simu sahihi inaachwa

  out.push({ json: {
    name: String(b.name ?? 'Bila jina').trim(),
    phone,
    need: String(b.need ?? b.message ?? '').trim().slice(0, 800),
    budget: Number(b.budget ?? 0),
    source: String(b.source ?? 'website'),
    received_at: new Date().toISOString()
  }});
}
return out;

// 2) Changanua jibu la AI; usianze kuanguka kama JSON ni mbovu
const lead = $('Hakiki & Safisha').first().json;
const raw = $json.choices?.[0]?.message?.content ?? '{}';
let d = {};
try { d = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); }
catch (e) { d = { score: 'WARM', reason: 'AI parse error - hakiki kwa mkono', summary: '', next_action: 'Piga simu' }; }

const emoji = d.score === 'HOT' ? '🔥' : d.score === 'COLD' ? '❄️' : '🌤️';
const text = emoji + ' LEAD MPYA (' + d.score + ')\n\n' +
  '👤 ' + lead.name + '\n' +
  '📞 ' + lead.phone + '\n' +
  '🎯 ' + (lead.need || 'hakuna maelezo').slice(0, 200) + '\n' +
  '💰 Bajeti: ' + (lead.budget ? 'TZS ' + lead.budget.toLocaleString('en-US') : 'haijatajwa') + '\n' +
  '📥 Chanzo: ' + lead.source + '\n\n' +
  '🧠 ' + (d.reason || '') + '\n' +
  '➡️ Hatua: ' + (d.next_action || 'Piga simu leo');

return [{ json: { ...lead, score: d.score ?? 'WARM', reason: d.reason ?? '', text, wa_link: 'https://wa.me/' + lead.phone.replace('+', '') } }];
